const cfg = $('CONFIG (EDIT ME) - Log Branch').first().json;
const body = $('1a. Webhook - Log Interaction').first().json.body;
const message = body.message || {};
const toolCall = (message.toolCalls && message.toolCalls[0]) || null;

// Vapi can send non-tool-call message types (end-of-call-report, status-update, etc.)
// to this same webhook. Don't crash on those — just pass through as a no-op.
if (!toolCall) {
  return [{ json: { skip: true, toolCallId: null } }];
}

let args = toolCall.function.arguments || {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch (e) { args = {}; }
}

const now = new Date();
return [{
  json: {
    skip: false,
    toolCallId: toolCall.id,
    googleSheetId: cfg.googleSheetId,
    // Flat, sheet-header-matching keys so '1c. Append Interaction Row' can
    // use auto-map instead of a manually maintained field list below it.
    // Add a new logInteraction argument -> add a matching key here with the
    // exact column name -> done, no separate node-by-node mapping to touch.
    Timestamp: now.toISOString(),
    CallDate: now.toLocaleDateString('en-CA', { timeZone: cfg.timeZone }),
    CallerName: args.callerName || '',
    CallerPhone: args.callerPhone || '',
    Topic: args.topic || '',
    Resolved: args.resolved,
    Details: args.details || '',
    GuestsCount: args.guestsCount || '',
    Drift: args.drift,
    CallConfidence: args.callConfidence || ''
  }
}];

const cfg = $('CONFIG (EDIT ME) - Summary Branch').first().json;
const rows = $input.all().map(i => i.json);
const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: cfg.timeZone });
const todays = rows.filter(r => r.CallDate === todayStr);

const resolved = todays.filter(r => String(r.Resolved).toLowerCase() === 'true');
const unresolved = todays.filter(r => String(r.Resolved).toLowerCase() !== 'true');

let summaryText;
if (todays.length === 0) {
  summaryText = `No calls came in for ${cfg.restaurantName} today.`;
} else {
  const parts = [];
  parts.push(`You had ${todays.length} call${todays.length === 1 ? '' : 's'} today at ${cfg.restaurantName}.`);
  if (resolved.length) {
    parts.push(`I answered ${resolved.length} directly: ` + resolved.map(r => `${r.CallerName || 'a caller'} asked about ${r.Topic}`).join('; ') + '.');
  }
  if (unresolved.length) {
    parts.push(`${unresolved.length} need your attention: ` + unresolved.map(r => `${r.CallerName || 'someone'} at ${r.CallerPhone}, about ${r.Topic}${r.Details ? ' — ' + r.Details : ''}`).join('; ') + '.');
  }
  summaryText = parts.join(' ');
}

return [{
  json: {
    count: todays.length,
    summaryText,
    ownerPhone: cfg.ownerPhoneNumber,
    assistantId: cfg.vapiSummaryAssistantId,
    phoneNumberId: cfg.vapiPhoneNumberId
  }
}];
